// Function to convert Excel serial dates (e.g. 38119) to YYYY-MM-DD
function excelDateToISODate(serial) {
  const utcDays = Math.floor(serial - 25569);
  const utcValue = utcDays * 86400; // seconds in a day
  const dateObj = new Date(utcValue * 1000);
  return dateObj.toISOString().split('T')[0];
}

// Function to validate basic email pattern
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Process all items in the n8n data stream
return $input.all().map(item => {
  const data = item.json;

  // 1. Process Date of Birth (Handles Excel Serial Numbers or Strings)
  let dob = null;
  if (typeof data.date_of_birth === 'number') {
    dob = excelDateToISODate(data.date_of_birth); // Converts 38119 -> 2004-05-01
  } else if (data.date_of_birth) {
    const parsedDob = new Date(data.date_of_birth);
    dob = !isNaN(parsedDob) ? parsedDob.toISOString().split('T')[0] : null;
  }

  // 2. Process Enrollment Date
  let enrollmentDate = null;
  if (data.enrollment_date) {
    const parsedEnrollment = new Date(data.enrollment_date);
    enrollmentDate = !isNaN(parsedEnrollment) ? parsedEnrollment.toISOString().split('T')[0] : null;
  }

  // 3. Clean and Validate Email
  const cleanEmail = (typeof data.email === 'string' && isValidEmail(data.email.trim())) 
    ? data.email.trim().toLowerCase() 
    : null;

  // 4. Standardize Gender
  let gender = data.gender ? data.gender.toString().trim().toUpperCase() : null;
  if (gender === 'M') gender = 'Male';
  else if (gender === 'F') gender = 'Female';

  // Return cleaned object back to n8n flow
  return {
    json: {
      student_id: Number(data.student_id),
      first_name: data.first_name ? data.first_name.trim() : null,
           gpa: typeof data.gpa === 'number' ? Number(data.gpa.toFixed(2)) : null,
      date_of_birth: dob,
      email: cleanEmail,
      gender: gender,
      enrollment_date: enrollmentDate,
      is_valid_record: cleanEmail !== null // Useful flag for downstream routing/filtering
    }
  };
});
